  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'creacion-de-objetos-utiles', 'Creación de Objetos Útiles', 'Desafío de invención campamentera y construcción artesanal donde los scouts elaboran artefactos prácticos con elementos naturales.', '<h2>📜 Descripción de Creación de Objetos Útiles</h2>
<p><b>Creación de Objetos Útiles</b> es un desafío de invención técnica, artesanía de rincón de patrulla y reutilización sustentable. En esta actividad, cada equipo recibe un conjunto de elementos naturales o de desecho de campamento (ej. <i>ramitas, piñas de pino, cordines y trozos de madera</i>) y dispone de un tiempo límite de 15 minutos para inventar y construir un artefacto práctico de uso campamentero.</p>
<p>Los objetos construidos pueden ser de variada naturaleza: <i>un portalamparas colgante para la carpa, un perchero de mochila, una escobilla de suelo silvestre, un porta-utensilios de cocina o un juego de mesa artesanal</i>. Al finalizar el tiempo de construcción, la patrulla expone su invento ante la unidad, explicando su utilidad práctica y los principios técnicos aplicados.</p>
<p>Esta actividad ejercita la habilidad manual, el pensamiento inventivo, la cultura del reciclaje y el trabajo colaborativo en Manada, Compañía, Tropa, Avanzada y Clan.</p>', '/uploads/creacion-de-objetos-utiles.webp', 'publicado', '{"areas": ["creatividad", "sociabilidad"], "unidades": ["manada", "compañía", "tropa", "avanzada", "clan"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Salón", "Exterior", "Campo Abierto"], "materiales": ["Ramitas", "Piñas de Pino", "Cordines"], "objetivos": ["Estimular la creatividad", "Aprender a seguir instrucciones", "Refuerzo de habilidades técnicas", "Trabajo en equipo"], "justificacion_areas": "Creación de Objetos Útiles potencia la creatividad al unir conocimientos teóricos y prácticos mediante habilidades técnicas y manuales en la elaboración de objetos campamenteros. Desarrolla la sociabilidad al fomentar el cuidado de la naturaleza y la preservación del mundo natural mediante el aprovechamiento ecológico de recursos.", "variaciones": "<b>Desafío de Utensilio de Cocina:</b> Construir exclusivamente herramientas para preparar la comida en el fogón.<br><b>Inventos con Material Reciclado:</b> Usar únicamente botellas plásticas y envases limpios traídos de casa.<br><b>Feria de Patentes Scout:</b> Vender la idea del invento a los dirigentes usando un sketch publicitario.", "recomendaciones": "Supervisar el uso seguro de amarras y herramientas cortantes si se utilizan. Fomentar el cuidado de la naturaleza.", "objetivos_educativos": [{"id": "8985ff05-ee84-4fba-af46-146c5374df89", "area": "Creatividad", "unidad": "Manada", "texto": "Participo en los talleres de manualidades que se hacen en la Manada.", "como_se_cumple": "Juntando ramitas secas y piñas del suelo para armar un portalamparas o un perchero sencillo con mis propias manos en la seisena."}, {"id": "789469d9-0a2c-4187-bead-5b9ed5d0cf72", "area": "Sociabilidad", "unidad": "Manada", "texto": "Cuido los animales y las plantas que hay en los lugares en que paseo y acampo.", "como_se_cumple": "Recolectando piñas y palitos sueltos de los caminitos sin romper las hojitas ni las ramas de los árboles vivos del campamento."}, {"id": "ccae8bbe-0001-4e5e-bbe4-077f60d9401f", "area": "Creatividad", "unidad": "Manada", "texto": "Hago trabajos cada vez mejores con mis manos.", "como_se_cumple": "Atando cordines de colores alrededor de las ramitas para sostener los útiles de la carpa de forma firme y ordenada."}, {"id": "03dceb73-d64f-46f6-994c-d5a2d7cbe9e3", "area": "Sociabilidad", "unidad": "Manada", "texto": "Ayudo en la limpieza y el mejoramiento de los lugares en que paseo y acampo.", "como_se_cumple": "Limpiando la zona de acampada de palos desordenados y usándolos para construir percheros de mochila para la seisena."}, {"id": "2a1587b7-9b40-40e1-9113-8ccd928e1464", "area": "Creatividad", "unidad": "Compañía", "texto": "Conozco y uso algunas técnicas de campismo y pionerismo.", "como_se_cumple": "Haciendo nudos llanos y amarres cuadrados simples con cordines para amarrar la madera seca y armar una escobilla de suelo o porta-utensilios."}, {"id": "9ed1f4d8-b2c7-405c-9f1b-9d1850f21f7a", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Ayudo en la limpieza y el mejoramiento de los lugares en que paseo y acampo.", "como_se_cumple": "Juntando las ramas caídas que ensucian los pasillos del campamento para reutilizarlas en percheros y útiles de rincón de patrulla."}, {"id": "b49b1e68-9cc5-4c76-9cd7-4d6f4c3c1ec6", "area": "Creatividad", "unidad": "Compañía", "texto": "Participo en el diseño e instalación de las construcciones de campamento.", "como_se_cumple": "Dibujando un croquis rápido y amarrando maderas con cordines junto a mi patrulla para equipar el rincón con un porta-platos o colgador."}, {"id": "385a0c5c-c0c0-46f9-8294-95c7af828da5", "area": "Sociabilidad", "unidad": "Compañía", "texto": "He participado con mi patrulla en proyectos de conservación.", "como_se_cumple": "Construyendo herramientas de campamento con piñas, cordines usados y madera caída sin generar basura ni dañar el bosque."}, {"id": "d8c45409-4dcd-4629-a764-cdf52e8b9340", "area": "Creatividad", "unidad": "Tropa", "texto": "Conozco y uso algunas técnicas de campismo y pionerismo.", "como_se_cumple": "Haciendo nudos llanos y amarres cuadrados simples con cordines para amarrar la madera seca y armar una escobilla de suelo o porta-utensilios."}, {"id": "bb7fb904-59e9-406c-a732-ff9805dc243c", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Ayudo en la limpieza y el mejoramiento de los lugares en que paseo y acampo.", "como_se_cumple": "Juntando las ramas caídas que ensucian los pasillos del campamento para reutilizarlas en percheros y útiles de rincón de patrulla."}, {"id": "78e8ab9b-5313-4642-8f12-8ca4e94ffa5c", "area": "Creatividad", "unidad": "Tropa", "texto": "Participo en el diseño e instalación de las construcciones de campamento.", "como_se_cumple": "Dibujando un croquis rápido y amarrando maderas con cordines junto a mi patrulla para equipar el rincón con un porta-platos o colgador."}, {"id": "46017e67-80b2-4334-a154-3c2d0dfda7e3", "area": "Sociabilidad", "unidad": "Tropa", "texto": "He participado con mi patrulla en proyectos de conservación.", "como_se_cumple": "Construyendo herramientas de campamento con piñas, cordines usados y madera caída sin generar basura ni dañar el bosque."}, {"id": "fe57c89e-be7b-46a1-b370-64df400355fa", "area": "Creatividad", "unidad": "Avanzada", "texto": "Trato de aprender más sobre cuestiones técnicas relacionadas con el sonido, la imagen, la mecánica, la informática y otros.", "como_se_cumple": "Probando amarres de palanca y ensambles mecánicos con cordines para crear inventos campamenteros articulados y resistentes."}, {"id": "7e7417a5-a16e-4ff3-843f-93e711d017d4", "area": "Sociabilidad", "unidad": "Avanzada", "texto": "Contribuyo a preservar la vida a través de la conservación de la integridad del mundo natural.", "como_se_cumple": "Aprovechando restos de madera y piñas secas para armar percheros y linternas ecológicas sin cortar vegetación nativa."}, {"id": "29eee8b1-a414-4df9-90e1-520a384fb9aa", "area": "Creatividad", "unidad": "Clan", "texto": "Uno los conocimientos teórico y práctico mediante la aplicación constante de mis habilidades técnicas y manuales.", "como_se_cumple": "Uniendo técnicas de pionerismo y amarras con madera reciclada para construir un porta-herramientas de servicio comunitario para el grupo."}, {"id": "c4f78e61-6790-4cf4-b477-993900b5bf02", "area": "Sociabilidad", "unidad": "Clan", "texto": "Contribuyo a preservar la vida a través de la conservación de la integridad del mundo natural.", "como_se_cumple": "Reutilizando cordines viejos y elementos sueltos del bosque para construir equipo campamentero bajo la regla de cero residuos."}]}'::jsonb, NOW(), NOW(), NULL, NULL
);

